const items = $input.all();
const pendingCount = items.length;
const todayStr = new Date().toLocaleDateString('en-US', { 
  weekday: 'long', 
  year: 'numeric', 
  month: 'short', 
  day: 'numeric' 
});

// 1. تجميع وتصنيف عدد المرشحين حسب الوظائف المتقدم إليها
const roleCounts = {};
for (const item of items) {
  const role = item.json.appliedPosition || 'General';
  roleCounts[role] = (roleCounts[role] || 0) + 1;
}

let rolesBreakdownHtml = '';
for (const [role, count] of Object.entries(roleCounts)) {
  rolesBreakdownHtml += `
    <li style="margin-bottom: 10px; color: #334155; font-size: 14px; list-style: none;">
      🔹 <strong>${role}:</strong> 
      <span style="background-color: #dbeafe; color: #1e40af; font-weight: bold; padding: 2px 8px; border-radius: 9999px; font-size: 12px; margin-left: 6px;">
        ${count} Candidate${count > 1 ? 's' : ''}
      </span>
    </li>
  `;
}

// 2. رابط الداشبورد التفاعلي الخاص بالورك فلو 3 (Workflow 3)
// استبدل الدومين برابط سيرفر الـ n8n الخاص بك
const dashboardUrl = "https://your-n8n-instance.com/webhook/ats-dashboard";

// 3. تصميم بريد إشعار تنبيهي أنيق وعصري
const htmlBody = `
<!DOCTYPE html>
<html>
<head><meta charset="utf-8"></head>
<body style="font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Helvetica, Arial, sans-serif; background-color: #f1f5f9; margin: 0; padding: 30px 15px;">
  <div style="max-width: 560px; margin: 0 auto; background-color: #ffffff; border-radius: 12px; border: 1px solid #e2e8f0; overflow: hidden; box-shadow: 0 4px 6px -1px rgba(0, 0, 0, 0.05);">

    <!-- Header -->
    <div style="background-color: #0f172a; color: #ffffff; padding: 24px; text-align: center;">
      <h2 style="margin: 0; font-size: 20px; font-weight: 700; letter-spacing: 0.3px;">⚡ Daily Recruitment Digest</h2>
      <p style="margin: 6px 0 0 0; color: #94a3b8; font-size: 13px;">${todayStr}</p>
    </div>

    <!-- Body Content -->
    <div style="padding: 28px 24px;">
      <p style="margin: 0 0 18px 0; color: #1e293b; font-size: 15px; line-height: 1.5;">
        Good morning! You have <strong>${pendingCount}</strong> qualified candidate(s) awaiting your decision today.
      </p>

      <!-- Roles Breakdown Box -->
      <div style="background-color: #f8fafc; border: 1px solid #e2e8f0; border-radius: 8px; padding: 16px 20px; margin-bottom: 24px;">
        <span style="font-size: 12px; color: #64748b; font-weight: 700; text-transform: uppercase; letter-spacing: 0.5px; display: block; margin-bottom: 12px;">
          📊 Candidates by Role:
        </span>
        <ul style="padding: 0; margin: 0;">
          ${rolesBreakdownHtml}
        </ul>
      </div>

      <!-- Call to Action Button to Workflow 3 Dashboard -->
      <div style="text-align: center; margin: 30px 0 10px 0;">
        <a href="${dashboardUrl}" target="_blank" style="background-color: #2563eb; color: #ffffff; text-decoration: none; padding: 12px 28px; border-radius: 8px; font-weight: 700; font-size: 14px; display: inline-block; box-shadow: 0 2px 4px rgba(37, 99, 235, 0.2);">
          🚀 Open ATS Web Dashboard
        </a>
      </div>

      <p style="text-align: center; color: #64748b; font-size: 12px; margin-top: 14px;">
        Review CV summaries, evaluate interviews, and manage the waiting list directly inside the dashboard.
      </p>
    </div>

    <!-- Footer -->
    <div style="background-color: #f8fafc; border-top: 1px solid #e2e8f0; padding: 14px; text-align: center; color: #94a3b8; font-size: 11px;">
      Automated via n8n Recruitment System &bull; Daily HR Alert
    </div>

  </div>
</body>
</html>
`;

return [{
  json: {
    pendingCount,
    todayStr,
    htmlBody
  }
}];
